import Foundation
import Compression

/// Static metadata catalogue. Entries are never executed by this app.
enum RustCatalog {
    static let reportedModeCount = 413

    // zlib-compressed TSV reconstructed from labels embedded in the supplied arm64 executable.
    private static let payload = #"""

"""#

    private static let decodedTSV: String = {
        guard let compressed = Data(base64Encoded: payload, options: .ignoreUnknownCharacters) else { return "" }
        var output = Data(count: 64 * 1024)
        let decodedCount = compressed.withUnsafeBytes { source in
            output.withUnsafeMutableBytes { destination in
                guard let sourcePointer = source.bindMemory(to: UInt8.self).baseAddress,
                      let destinationPointer = destination.bindMemory(to: UInt8.self).baseAddress else {
                    return 0
                }
                return compression_decode_buffer(
                    destinationPointer, destination.count,
                    sourcePointer, source.count,
                    nil, COMPRESSION_ZLIB
                )
            }
        }
        guard decodedCount > 0 else { return "" }
        output.count = decodedCount
        return String(data: output, encoding: .utf8) ?? ""
    }()

    static let modes: [RustMode] = decodedTSV
        .split(whereSeparator: \.isNewline)
        .dropFirst()
        .compactMap { row in
            let columns = row.split(separator: "\t", omittingEmptySubsequences: false)
            guard columns.count == 3, let id = Int(columns[0]) else { return nil }
            return RustMode(id: id, family: String(columns[1]), title: String(columns[2]))
        }

    static let families = Array(Set(modes.map(\.family))).sorted()
}
